  "components.chimera-eyes.desc": "Ao forjar:\nSe o equipamento forjado tiver os marcadores Caos ou Olho, Olhos de Quimera concede uma melhoria aleatória aos feitiços de Olho que você conhece\n\nSe este componente conceder uma ou mais melhorias, ele é destruído",
