  "components.frost-core.desc": "Ao coletar:\nCause 10 de dano de Gelo e 3 turnos de congelamento nos inimigos a até 2 casas\nCada vez que este efeito se repete, seu raio aumenta em 1\nEste efeito se repete a cada 6 turnos até o fim do nível",
