  "components.stormglass-eye.desc": "Ao coletar:\nInvoque uma Nuvem de Tempestade sobre cada inimigo na linha de visão\nCada nuvem tem 50% de chance de causar 25 de dano de Raio a cada turno\nNuvens de Tempestade duram 5 turnos\nEste efeito se repete a cada 6 turnos até o fim do nível",
