  "components.stormsong-note.desc": "Ao forjar:\nSe o equipamento forjado tiver o marcador Gelo, ele invoca Nevascas em locais aleatórios quando você lança manualmente um feitiço de Gelo\nSe o equipamento forjado tiver o marcador Raio, ele invoca Nuvens de Tempestade em locais aleatórios quando você lança manualmente um feitiço de Raio\nO número de nuvens criadas é igual ao nível do feitiço\nO dano e a duração das nuvens escalam com o equipamento",
