  "components.warlord-s-skull.desc": "Ao forjar:\nSe o equipamento forjado concederia bônus de dano, duração, alcance ou número de alvos, ele concede esses bônus para dano de lacaios, duração de lacaios, alcance de lacaios ou número de invocações em vez disso",
