  "equipment.artificer-s-abacus.desc": "Quando você lança um feitiço manualmente, manipule o ábaco\nSe o nível do feitiço for ímpar, subtraia essa quantidade de contas\nSe o nível do feitiço for par, adicione essa quantidade de contas\nQuando o número de contas no ábaco for igual ao número do reino, reinicie o ábaco e ative o efeito ao coletar de um dos componentes usados para forjá-lo\nO Ábaco do Artífice só pode ser ativado enquanto o número do turno for menor que o número do reino\n\nContas Atuais: 0",
