  "equipment.artificer-s-hammer.desc": "Quando você obtém uma peça de equipamento, ativa o efeito ao coletar de um dos componentes usados para forjar o Martelo do Artífice\nO Martelo do Artífice pode ativar cada um de seus componentes armazenados uma vez por nível\n\nComponentes restantes: 0 / 0",
