  "equipment.artificer-s-mirror.desc": "Ao coletar um componente, ativa o efeito ao coletar de um dos componentes usados para forjar o Espelho do Artífice\nSe o componente coletado corresponder a um dos componentes usados para forjar o Espelho do Artífice, ganhe uma cópia dele em vez disso",
