  "equipment.artificer-s-rod.desc": "Lançar magias com marcadores que correspondam aos componentes usados para forjar o Bastão do Artífice o recarrega\nQuando todos os requisitos de marcadores forem atendidos, ativa o efeito ao coletar de cada um dos componentes usados para forjá-lo\nPode ser ativado uma vez por nível",
