  "equipment.codex-necronomicus.desc": "Quando você lançar manualmente uma magia de Trevas, há uma chance de ela receber uma melhoria aleatória\nQuando uma magia é melhorada dessa forma, o custo de PV de todas as magias e equipamentos aumenta em 1\nA chance de uma magia ser melhorada é igual à sua maestria de Trevas",
