  "equipment.treelord-staff.desc": "Quando você lança um feitiço de Natureza de nível 3 ou superior, invoque um Ente por perto",
  "equipment.treelord-staff.name": "Cajado do Senhor das Árvores",
  "equipment.tundra-mantle.desc": "A cada turno, inimigos encharcados em um raio de 5 casas ficam congelados por 3 turnos",
  "equipment.tundra-mantle.name": "Manto da Tundra",
  "equipment.twilight-lantern.desc": "Quando você lança um feitiço de Trevas ou Sagrado, ganhe Sentinela do Crepúsculo com duração igual ao nível do feitiço\nSentinela do Crepúsculo causa 6 de dano de Trevas a um inimigo aleatório na linha de visão a cada turno e, em seguida, 6 de dano Sagrado a outro",
  "equipment.twilight-lantern.name": "Lanterna do Crepúsculo",
  "equipment.twilight-oculus.desc": "Na primeira vez que um inimigo sofre dano de Trevas ou Sagrado, ele recebe -25 de resistência a Trevas e Sagrado",
  "equipment.twilight-oculus.name": "Óculo do Crepúsculo",
  "equipment.tzango-s-cleaver.desc": "No início de cada nível, lance Choque Mortal em até 2 inimigos adjacentes aleatórios",
  "equipment.tzango-s-cleaver.name": "Cutelo de Tzango",
  "equipment.umbral-totem.name": "Totem Umbral",
  "equipment.unblinking-eye.name": "Olho Que Não Pisca",
  "equipment.unholy-expurgator.desc": "Aliados Trevas e Sagrado aprendem Expurgar\nExpurgar é uma magia corpo a corpo\nExpurgar causa 8 de dano de Trevas, Sagrado e Físico\nExpurgar tem 3 turnos de recarga",
  "equipment.unholy-expurgator.name": "Expurgador Profano",
  "equipment.vampiric-vestments.desc": "Quando uma unidade Viva morre, cura 5 PV",
  "equipment.vampiric-vestments.name": "Vestimentas Vampíricas",
  "equipment.veilpiercer-s-monocle.desc": "Ganha clareza ao lançar um feitiço de Translocação\nA duração do efeito é igual ao nível do feitiço",
  "equipment.veilpiercer-s-monocle.name": "Monóculo do Fura-Véus",
  "equipment.venom-spitter-casque.desc": "Aliados Vivo e Natureza aprendem Cuspe de Veneno\nCuspe de Veneno causa 4 de dano de Veneno e inflige Veneno por 10 turnos\nCuspe de Veneno tem 3 de alcance e 3 turnos de recarga",
  "equipment.venom-spitter-casque.name": "Elmo Cuspidor de Veneno",
  "equipment.venomancer-s-vial.desc": "Inimigos envenenados sofrem 4 de dano de Veneno adicional a cada turno",
  "equipment.venomancer-s-vial.name": "Frasco do Venomante",
  "equipment.vial-of-ambrosia.desc": "No início de cada nível, ganhe 10 turnos de Clareza",
  "equipment.vial-of-ambrosia.name": "Frasco de Ambrosia",
  "equipment.vile-dagger.name": "Adaga Vil",
  "equipment.void-hunter-s-sigil.desc": "Para cada unidade Arcana que morrer, um dos seus feitiços Arcanos recupera 1 carga\nAo final de cada nível, uma Fenda contendo inimigos Arcanos é criada",
  "equipment.void-hunter-s-sigil.name": "Sigilo do Caçador do Vazio",
  "equipment.void-oculus.desc": "Na primeira vez que um inimigo sofre dano de Trevas ou Arcano, ele recebe -25 de resistência a Trevas e Arcano",
  "equipment.void-oculus.name": "Óculo do Vazio",
  "equipment.void-spike-stone.desc": "Quando você ou um de seus aliados Arcano ou Morto-vivo sofre dano de um inimigo, causa 5 de dano de Arcano ao inimigo",
  "equipment.void-spike-stone.name": "Pedra de Espinho do Vazio",
  "equipment.void-traveler-s-cloak.desc": "Quando você se teletransporta, ganhe 2 de SH",
  "equipment.void-traveler-s-cloak.name": "Manto do Viajante do Vazio",
  "equipment.voidflame-lantern.desc": "Ao lançar um feitiço de Fogo ou Arcano, ganhe Carga Estelar com duração igual ao nível do feitiço\nCarga Estelar causa 6 de dano Arcano a um inimigo aleatório na linha de visão a cada turno e, em seguida, 6 de dano de Fogo a outro",
  "equipment.voidflame-lantern.name": "Lanterna da Chama do Vazio",
  "equipment.volcanic-lance.desc": "Quando você lança uma magia de Fogo mirando em um inimigo, dispara um raio destrutivo em direção ao alvo\nO raio destrói paredes e causa dano de Fogo igual à sua maestria em Fogo",
  "equipment.volcanic-lance.name": "Lança Vulcânica",
  "equipment.voodoo-doll.desc": "No início de cada nível, os 5 inimigos com mais PV ficam Ligados por Vodu\nQuando você sofre dano, os inimigos Ligados por Vodu sofrem esse dano\nQuando você gasta PV, Ligados por Vodu causa essa mesma quantidade de dano Físico aos inimigos",
  "equipment.voodoo-doll.name": "Boneco de Vodu",
  "equipment.warlord-banner.name": "Estandarte do Senhor da Guerra",
  "equipment.warlord-helm.name": "Elmo do Senhor da Guerra",
  "equipment.warlord-vestments.name": "Vestes do Senhor da Guerra",
  "equipment.wild-healing-staff.desc": "Quando você lança uma magia de Natureza, você e seus aliados Vivo curam 5 PV",
  "equipment.wild-healing-staff.name": "Cajado da Cura Selvagem",
  "equipment.winged-shoes.desc": "Concede Voo",
  "equipment.winged-shoes.name": "Sapatos Alados",
  "equipment.winter-links.desc": "Quando um inimigo morre por dano de Gelo ou Trevas, um inimigo aleatório na linha de visão dele em até 3 casas sofre 9 de dano desse tipo",
  "equipment.winter-links.name": "Elos do Inverno",
  "equipment.wintersting.desc": "A cada 80 de dano causado a inimigos por feitiços ou equipamentos de Gelo, lance Ferrão Venenoso em um inimigo aleatório\nDano Causado: 0",
  "equipment.wintersting.name": "Ferrão Invernal",
  "equipment.witching-hourglass.desc": "Quando um inimigo desperta do sono, invoque um Fantasma temporário perto dele",
  "equipment.witching-hourglass.name": "Ampulheta da Bruxaria",
  "equipment.woadwyrd.desc": "A cada 100 de dano causado a inimigos por feitiços ou equipamentos de Natureza, lance Maldição Sombria em um inimigo aleatório\nDano Causado: 0",
  "equipment.woadwyrd.name": "Fado Índigo",
  "equipment.wound-rot-amulet.desc": "Inimigos recebem 3 turnos de veneno quando sofrem dano Físico",
  "equipment.wound-rot-amulet.name": "Amuleto da Podridão de Feridas",
  "equipment.wrath-links.desc": "Quando um inimigo morre por dano Sagrado ou de Raio, um inimigo aleatório na linha de visão dele em até 3 casas sofre 9 de dano desse tipo",
  "equipment.wrath-links.name": "Elos da Ira",
  "equipment.wyrm-spirit-armor.desc": "Quando um dos seus aliados Dragão morre, você ganha 10% de resistência aos tipos de dano correspondentes às suas etiquetas\nReinicia a cada nível",
  "equipment.wyrm-spirit-armor.name": "Armadura do Espírito de Wyrm",
